    state.remaining -= 1;
    if (state.remaining <= 0) {
      state.remaining = 0;
      completePhase();
    }
    render();
  }

  function completePhase() {
    if (state.mode === FOCUS) {
      state.plants += 1;
      const mins = Math.round(focusSeconds() / 60);
      state.totalMin += mins;
      // streak: consecutive calendar days
      const today = new Date().toDateString();
      const yest = new Date(Date.now() - 864e5).toDateString();
      if (state.lastCompletedDay === undefined || state.lastCompletedDay === null || state.lastCompletedDay === "") {
        state.currentStreak = 1;
      } else if (state.lastCompletedDay === yest) {
        state.currentStreak += 1;
      } else if (state.lastCompletedDay !== today) {
        state.currentStreak = 1;
      }
      state.lastCompletedDay = today;
      state.longestStreak = Math.max(state.longestStreak, state.currentStreak);
      flash();
      el.status.textContent = "🌾 Focus complete! A plant has grown.";
    } else {
      el.status.textContent = "✨ Break'"'s over. Back to it"'!";
    }
    state.mode = state.mode === FOCUS ? BREAK : FOCUS;
    state.remaining = state.mode === FOCUS ? focusSeconds() : breakSeconds();
    save();
  }

  function flash() {
    el.time.classList.add("flash");
    setTimeout(() => el.time.classList.remove("flash"), 1200);
  }

  // ---------- controls ----------
  function setRunning(on) {
    state.running = on;
    clearInterval(timerId);
    if (on) timerId = setInterval(tick, 1000);
    el.start.textContent = on ? "Pause" : "Resume";
    save();
    render();
  }

  el.start.addEventListener("click", () => setRunning(!state.running));

  el.reset.addEventListener("click", () => {
    clearInterval(timerId);
    state.running = false;
    state.mode = FOCUS;
    state.remaining = focusSeconds();
    el.status.textContent = "";
    el.start.textContent = "Start";
    save();
    render();
  });

  el.skip.addEventListener("click", () => {
    clearInterval(timerId);
    state.running = false;
    state.remaining = 0;
    el.start.textContent = "Start";
    completePhase();
    render();
  });

  el.clear.addEventListener("click", () => {
    if (!confirm("Clear all plants and progress?")) return;
    clearInterval(timerId);
    state = { mode: FOCUS, running: false, remaining: focusSeconds(), plants: 0, totalMin: 0, longestStreak: 0, currentStreak: 0, lastCompletedDay: null };
    el.status.textContent = "";
    el.start.textContent = "Start";
    save();
    render();
  });

  [el.focusMin, el.breakMin].forEach((inp) =>
    inp.addEventListener("change", () => {
      if (!state.running && state.plants === 0 && state.totalMin === 0) {
        state.mode = FOCUS;
        state.remaining = focusSeconds();
        render();
      }
    })
  );

  // ---------- rendering ----------
  function render() {
    el.time.textContent = format(state.remaining);
    el.mode.textContent = state.mode === FOCUS ? "Focus" : "Break";
    el.mode.style.color = state.mode === BREAK ? "var(--bloom)" : "";
    renderWeather();
    renderGarden();
  }

  function renderWeather() {
    const n = state.plants;
    let sky = "☀️ Sunny";
    if (n >= 10) sky = "🌤️ Bright";
    if (n >= 25) sky = "🌸 Blooming";
    if (n >= 50) sky = "🌳 Flourishing";
    el.weather.textContent = `${sky} · ${n} plant${n === 1 ? "" : "s"} · ${state.totalMin} min focused`;
  }

  function R(min, max) { return min + Math.random() * (max - min); }

  function plantEl(idx) {
    const d = document.createElement("div");
    d.className = "plant";
    const left = 6 + idx * 17 + R(-2, 2);
    d.style.left = `${left}%`;

    const status = state.plants < 10 ? "growing" : Math.random() < 0.7 ? "tall" : "bloom";
    let height, leafCount, hasBloom;

    if (status === "growing") {
      height = R(24, 42); leafCount = idx % 3; hasBloom = false;
    } else if (status === "bloom") {
      height = R(60, 84); leafCount = 4; hasBloom = true;
    } else {
      height = R(52, 74); leafCount = 3; hasBloom = false;
    }

    const stem = document.createElement("div");
    stem.className = "stem";
    stem.style.height = `${height}px`;
    d.appendChild(stem);

    for (let l = 0; l < leafCount; l++) {
      const leaf = document.createElement("div");
      leaf.className = "leaf";
      leaf.style.left = l % 2 === 0 ? `${-8 - R(0, 6)}px` : `${14 + R(0, 6)}px`;
      leaf.style.top = `${R(8, height * 0.7)}px`;
      leaf.style.transform = l % 2 === 0 ? "rotate(-20deg)" : "rotate(160deg)";
      leaf.style.background = `linear-gradient(135deg, hsl(${118 + R(0, 20)}, 60%, ${48 + R(0, 12)}%), #2e7d32)`;
      d.appendChild(leaf);
    }

    if (hasBloom) {
      const b = document.createElement("div");
      b.className = "bloom";
      b.style.left = "50%";
      b.style.transform = "translateX(-50%)";
      b.style.top = `${Math.max(4, height)}px`;
      d.appendChild(b);
    }
    return d;
  }

  function renderGarden() {
    el.soil.innerHTML = "";

    if (state.plants === 0) {
      const empty = document.createElement("div");
      empty.className = "empty";
      empty.innerHTML = `<span class="big">🪴</span>Finish your first focus session to plant a seed.</div>`;
      empty.innerHTML = `<span class="big">🪴</span>Finish your first focus session to plant a seed.`;
      el.soil.appendChild(empty);
    } else {
      for (let i = 0; i < state.plants; i++) {
        el.soil.appendChild(plantEl(i));
      }
    }

    const goals = [1, 5, 10, 25, 50];
    const next = goals.find((g) => state.plants < g);
    el.milestone.textContent = next
      ? `Next milestone: ${next} plants (${state.plants}/${next}) · 🔥 ${state.currentStreak}-day streak (best ${state.longestStreak})`
      : `🏆 All milestones reached · best streak ${state.longestStreak} days · 🔥 current ${state.currentStreak}`;
  }

  // ---------- mirror (text view) ----------
  el.mirror.addEventListener("click", () => {
    const rows = [];
    rows.push(`Focus Garden — ${state.plants} plant(s)`);
    rows.push(`Focused ${state.totalMin} minutes total · ${state.currentStreak}-day streak (best ${state.longestStreak})`);
    let bar = "";
    for (let i = 0; i < state.plants; i++) bar += "🌱";
    bar += state.plants >= 10 ? " 🌳" : "";
    rows.push(bar || "🪴 nothing yet");
    alert(rows.join("'"\\n\"));
  });

  // ---------- init ----------
  load();
  if ("'!state.remaining) state.remaining = focusSeconds();
  render();
})();
</script>
